// by tag name -> collection of ALL matches
document.getElementsByTagName("li");                 // 3 items
document.getElementsByTagName("li")[2].style.color = "purple";
document.getElementsByTagName("li").length;          // 3

// by class name -> collection, even for a single match
document.getElementsByClassName("btn")[0].style.color = "red";

// by id -> ONE element
document.getElementById("title").innerHTML = "Text Changed With Javascript";

// querySelector -> first match of a CSS selector
document.querySelector("h1");
document.querySelector("#title");
document.querySelector(".btn");
document.querySelector("li a");        // descendant (space)
document.querySelector("li.item");     // same element (no space)
document.querySelector("#list a");

// querySelectorAll -> all matches
document.querySelectorAll("#list .item")[2].style.color = "blue";
